'use client'

import { useEffect, useRef, useState } from 'react'
import Link from 'next/link'

const PHI = 1.618033988749895

interface Product {
    id: string
    name: string
    price: number
    modelUrl?: string
}

interface HeroSectionProps {
    featuredProducts: Product[]
}

export default function HeroSection({ featuredProducts }: HeroSectionProps) {
    const canvasRef = useRef<HTMLCanvasElement>(null)
    const [currentProductIndex, setCurrentProductIndex] = useState(0)

    // Fourier background animation
    useEffect(() => {
        const canvas = canvasRef.current
        if (!canvas) return
        const ctx = canvas.getContext('2d')
        if (!ctx) return

        let animationFrameId: number
        let time = 0

        const resize = () => {
            canvas.width = window.innerWidth
            canvas.height = 600
        }
        window.addEventListener('resize', resize)
        resize()

        const epicycles = Array.from({ length: 5 }, (_, i) => ({
            radius: 60 / Math.pow(PHI, i * 0.5),
            frequency: Math.pow(PHI, i * 0.3) * 0.08,
            phase: (Math.PI * 2 * i) / 5
        }))

        const render = () => {
            time += 0.003
            ctx.fillStyle = 'transparent'
            ctx.clearRect(0, 0, canvas.width, canvas.height)

            const centerX = canvas.width / 2
            const centerY = 300

            let currentX = centerX
            let currentY = centerY

            epicycles.forEach((epicycle, i) => {
                const angle = time * epicycle.frequency + epicycle.phase

                ctx.globalAlpha = 0.08
                ctx.strokeStyle = i % 2 === 0 ? '#7E57C2' : '#4DD0E1'
                ctx.lineWidth = 1

                ctx.beginPath()
                ctx.arc(currentX, currentY, epicycle.radius, 0, Math.PI * 2)
                ctx.stroke()

                const nextX = currentX + Math.cos(angle) * epicycle.radius
                const nextY = currentY + Math.sin(angle) * epicycle.radius

                ctx.beginPath()
                ctx.moveTo(currentX, currentY)
                ctx.lineTo(nextX, nextY)
                ctx.stroke()

                currentX = nextX
                currentY = nextY
            })

            ctx.globalAlpha = 1
            animationFrameId = requestAnimationFrame(render)
        }

        render()

        return () => {
            window.removeEventListener('resize', resize)
            cancelAnimationFrame(animationFrameId)
        }
    }, [])

    // Auto-rotate products
    useEffect(() => {
        if (featuredProducts.length <= 1) return
        const interval = setInterval(() => {
            setCurrentProductIndex((prev) => (prev + 1) % featuredProducts.length)
        }, 5000)
        return () => clearInterval(interval)
    }, [featuredProducts.length])

    const currentProduct = featuredProducts[currentProductIndex] || {
        id: '0',
        name: 'Premium 3D Print',
        price: 99.99
    }

    return (
        <section className="relative h-[600px] flex items-center justify-center overflow-hidden bg-gradient-to-b from-black via-purple-900/10 to-black">
            {/* Fourier Background */}
            <canvas ref={canvasRef} className="absolute inset-0" />

            {/* Content */}
            <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                <h1 className="text-5xl md:text-7xl font-bold mb-6 bg-gradient-to-r from-cyan-400 via-purple-500 to-pink-500 bg-clip-text text-transparent">
                    Precision 3D Printing
                </h1>

                <p className="text-xl md:text-2xl text-gray-300 mb-8 max-w-2xl mx-auto">
                    Transform your ideas into reality with cutting-edge additive manufacturing
                </p>

                {/* Product Carousel */}
                <div className="mb-8">
                    <div className="inline-block px-6 py-3 bg-white/5 backdrop-blur-sm border border-white/10 rounded-lg">
                        <p className="text-sm text-gray-400 mb-1">Featured Product</p>
                        <h3 className="text-2xl font-bold text-white">{currentProduct.name}</h3>
                        <p className="text-cyan-400 text-lg mt-1">${currentProduct.price.toFixed(2)}</p>
                    </div>
                </div>

                {/* CTA Buttons */}
                <div className="flex flex-col sm:flex-row gap-4 justify-center">
                    <Link
                        href="/admin/products/new"
                        className="px-8 py-4 bg-gradient-to-r from-cyan-500 to-purple-600 text-white font-bold rounded-full hover:shadow-lg hover:shadow-cyan-500/50 transition-all transform hover:scale-105"
                    >
                        Configure Now
                    </Link>
                    <Link
                        href="/products"
                        className="px-8 py-4 bg-white/10 backdrop-blur-sm border border-white/20 text-white font-bold rounded-full hover:bg-white/20 transition-all"
                    >
                        Browse Catalog
                    </Link>
                </div>

                {/* Carousel Indicators */}
                {featuredProducts.length > 1 && (
                    <div className="flex justify-center gap-2 mt-8">
                        {featuredProducts.map((_, index) => (
                            <button
                                key={index}
                                onClick={() => setCurrentProductIndex(index)}
                                className={`w-2 h-2 rounded-full transition-all ${index === currentProductIndex
                                    ? 'bg-cyan-400 w-8'
                                    : 'bg-white/30 hover:bg-white/50'
                                    }`}
                            />
                        ))}
                    </div>
                )}
            </div>
        </section>
    )
}
